Definition dbp_seg2_post (sp : word) (gp tp : word) (s0v s1v s2v : word) (s3 s4 s5 s6 s7 s8 s9 s10 s11 rav : word) (F : bvmap 5 word) (fc : bv 32)
    (R E bq beg en bpos lpos lo : Z) (pad7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v a0 a1 a2 a3 a4 a5 a6 a7 s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp); (R, R + 48); (E, E + 24)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ rw_cells usegs m' R (OptSrCells pad7 bq beg en bpos lpos)
    /\ rw_cells usegs m' E (ErrCodeCells EC_clear).

Definition dbp_seg2_stmt : Prop := forall (R E bq beg en bpos lpos lo : Z) (pad7 j8 j40 ej : list byte)
    (sp : word) gp tp (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (s0v s1v s2v rav s2x : word)
    (F : bvmap 5 word) fc (m : mem),
  rw_cells usegs m (bv_unsigned sp - 80) [CB 8 j8] ->
  rw_cells usegs m (bv_unsigned sp - 72) (SrCells bq beg en bpos lpos) ->
  rw_cells usegs m (bv_unsigned sp - 32) [C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
  rw_cells usegs m R [C1 (b8 0); CB 7 pad7; CB 40 j40] -> bv_unsigned sp <= R -> R + 48 <= 2^64 ->
  rw_cells usegs m E [CB 24 ej] -> bv_unsigned sp <= E -> E + 24 <= 2^64 -> (R + 48 <= E \/ E + 24 <= R) ->
  0 <= bq < 2^64 -> 0 <= beg < 2^64 -> 0 <= en < 2^64 -> 0 <= bpos < 2^64 -> 0 <= lpos < 2^64 ->
  stk usegs m lo (bv_unsigned sp - 80) -> lo + 80 <= bv_unsigned sp -> hceil <= lo -> bv_unsigned rav mod 2 = 0 ->
  mem_inv usegs m ->
  evt usegs (dbp_seg2_post sp gp tp s0v s1v s2v s3 s4 s5 s6 s7 s8 s9 s10 s11 rav F fc R E bq beg en bpos lpos lo pad7 m)
    (MS (mkR rax (wz (bv_unsigned sp - 80)) gp tp t0 t1 t2 (wz E) (wz R) a0 a1 a2 a3 a4 a5 a6 a7 s2x s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_DBP_RET) fc None m (seg_rom usegs)).

