Lemma mb_b12_range : forall b es insz n x,
  mb_addr_ok b (mb_put_es es insz n x) -> mb_ok es insz -> 1 <= n ->
  0 <= fst (mb_b1 b es insz n x) /\ fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x) <= hceil
  /\ 0 <= fst (mb_b2 b es insz n x) /\ fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x) <= hceil.
Proof.
  intros b es insz n x AOK OK N1. hcb. pose proof AOK as (AD & _). pose proof (mb_ok_bounds _ _ OK) as [IB CB0].
  unfold mb_b2, mb_b1. destruct (mb_need es insz n) eqn:ND; [destruct (mb_full es insz) eqn:FU|]; cbn [andb negb fst snd].
  - destruct (mb_shape_full b es insz n x OK N1 FU) as (_ & EES & EINS & _ & EMO & EOP & EOE & NG & I0).
    destruct (AD x (mb_grow es insz n) ltac:(rewrite EES; apply in_app_iff; right; left; reflexivity)) as (X0 & _ & G0 & XH). lia.
  - destruct (mb_shape_part b es insz n x OK N1 FU ND) as (P & xl & sl & EesP & EES & _ & EMO & ELA & ELS & ECI & EOP & OP1 & OPS & NGT & EOE & OEG & CP0).
    rewrite ELA, EOP. destruct (AD xl sl ltac:(rewrite EES, EesP; apply in_app_iff; left; apply in_app_iff; right; left; reflexivity)) as (X0 & _ & S0 & XH).
    destruct (AD x (mb_grow es insz n) ltac:(rewrite EES; apply in_app_iff; right; left; reflexivity)) as (X1 & _ & G0 & XH1).
    rewrite EesP, mb_cap_snoc. lia.
  - destruct (mb_shape_noneed b es insz n OK N1 ND) as (P & xl & sl & EesP & FU & _ & _ & ELA & ELS & ECI & EOP & OP1 & OPN & EOE & CP0).
    rewrite ELA, EOP. assert (EES : mb_put_es es insz n x = es) by (unfold mb_put_es; rewrite ND; reflexivity).
    destruct (AD xl sl ltac:(rewrite EES, EesP; apply in_app_iff; right; left; reflexivity)) as (X0 & _ & S0 & XH). lia.
Qed.

Definition put_seg2_W (lo : Z) (sp : word) (b : Z) (es : list mbe) (insz n x : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp);
   (fst (mb_b1 b es insz n x), fst (mb_b1 b es insz n x) + snd (mb_b1 b es insz n x));
   (fst (mb_b2 b es insz n x), fst (mb_b2 b es insz n x) + snd (mb_b2 b es insz n x));
   (b + 24, b + 64)]%Z.

Definition put_seg2_post (sp : word) (gp tp : word) (s0v s1v s2v s3v : word) (s4 s5 s6 s7 s8 s9 s10 s11 rav : word) (F : bvmap 5 word) (fc : bv 32)
    (b : Z) (es : list mbe) (insz n x src lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR rav sp gp tp t0 t1 t2 s0v s1v (wz n) a1 a2 a3 a4 a5 a6 a7 s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc rav) fc None m' (seg_rom usegs)
    /\ munch (put_seg2_W lo sp b es insz n x) m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp)
    /\ bytes_at usegs m' src bs
    /\ MBuf m' b (mb_put_es es insz n x) (insz + n).

Definition put_seg2_stmt : Prop := forall (rd cbp b : Z) (es : list mbe) (insz n x src E lo : Z) (bs pad7 j8 j16a j16b : list byte)
    (sp : word) gp tp (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (s0v s1v s2v s3v rav : word)
    (F : bvmap 5 word) fc (m : mem),
  MBmid m b es insz n x -> mb_ok es insz -> 1 <= n -> insz + n <= 2^30 ->
  rw_cells usegs m (bv_unsigned sp - 128) [CB 8 j8] ->
  rw_cells usegs m (bv_unsigned sp - 120) (OptSrCells pad7 b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n)) ->
  rw_cells usegs m (bv_unsigned sp - 72) [CB 16 j16a; CB 16 j16b; C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav] ->
  rw_cells usegs m rd [C8 (wz b)] -> bv_unsigned sp <= rd -> rd + 8 <= 2^64 ->
  rw_cells usegs m cbp [C8 (wz src); C8 (wz n)] -> bv_unsigned sp <= cbp -> cbp + 16 <= 2^64 ->
  rw_cells usegs m E (ErrCodeCells EC_clear) -> bv_unsigned sp <= E -> E + 24 <= 2^64 ->
  bytes_at usegs m src bs -> zlength bs = n ->
  (forall x' s', In (x', s') (mb_put_es es insz n x) -> src + n <= x' \/ x' + 24 + s' <= src) ->
  (src + n <= lo \/ bv_unsigned sp <= src) -> (src + n <= b \/ b + 64 <= src) ->
  bv_unsigned sp <= b -> (cbp + 16 <= b \/ b + 64 <= cbp) -> (rd + 8 <= b + 24 \/ b + 64 <= rd) -> (E + 24 <= b \/ b + 64 <= E) ->
  stk usegs m lo (bv_unsigned sp - 128) -> lo + 224 <= bv_unsigned sp -> hceil <= lo -> bv_unsigned rav mod 2 = 0 ->
  (* [comment removed for export] *)
  cbp mod 8 = 0 -> cbp + 16 < 2^64 -> 0 < src -> src + n < 2^64 -> bv_unsigned sp mod 16 = 0 ->
  mem_inv usegs m ->
  evt usegs (put_seg2_post sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 rav F fc b es insz n x src lo bs m)
    (MS (mkR rax (wz (bv_unsigned sp - 128)) gp tp t0 t1 t2 (wz rd) (wz cbp) a0 a1 a2 a3 a4 a5 a6 a7 (wz E) s3v s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_PUT_RET1) fc None m (seg_rom usegs)).

